1632	func (l *Log) uploadMigrationBatches(ctx context.Context, requests []*dynamodb.WriteRequest) error {
1633		if len(requests) == 0 {
1634			return nil
1635		}
1636		batches := make([][]*dynamodb.WriteRequest, 0, (len(requests)+DynamoBatchSize-1)/DynamoBatchSize)
1637		for len(requests) > 0 {
1638			batchSize := DynamoBatchSize
1639			if len(requests) < batchSize {
1640				batchSize = len(requests)
1641			}
1642			batches = append(batches, requests[:batchSize])
1643			requests = requests[batchSize:]
1644		}
1645	
1646		workerSlots := make(chan struct{}, maxMigrationWorkers)
1647		workerErrors := make(chan error, len(batches))
1648		var workers sync.WaitGroup
1649		for _, batch := range batches {
1650			select {
1651			case workerSlots <- struct{}{}:
1652			case <-ctx.Done():
1653				workers.Wait()
1654				return trace.Wrap(ctx.Err())
1655			}
1656			workers.Add(1)
1657			go func(batch []*dynamodb.WriteRequest) {
1658				defer workers.Done()
1659				defer func() { <-workerSlots }()
1660				if err := l.uploadBatch(ctx, batch); err != nil {
1661					records := make([]log.Fields, 0, len(batch))
1662					for _, request := range batch {
1663						if request.PutRequest == nil {
1664							continue
1665						}
1666						record := log.Fields{}
